import { expect, test } from 'vitest'
import { lintTicket } from '../scripts/ticket-lint.mjs'

// docs/tickets.md template, criteria and size rules; #322 bundled three slices under five
// packed criteria, which these checks refuse.
const ticket = ({
  size = 'Migrations 0 · New screens 1 · Owned frames 2 · Journeys 0 · Proofs 3',
  criteria = ['- [ ] The list shows archived medicines - Evidence: component test'],
  extra = '',
} = {}) =>
  [
    '> _This was generated by AI during triage._',
    '## What to build',
    'Show archived medicines.',
    extra,
    '## Ownership',
    '- Owns: archive confirmation (292·S5)',
    '- Out of scope: restore (#323)',
    '## Size',
    size,
    '## Acceptance criteria',
    ...criteria,
  ].join('\n')

test('a template-shaped ticket passes', () => {
  expect(lintTicket(ticket())).toEqual([])
  expect(lintTicket(ticket({ extra: '## Rules\n- x\n## Current state\n- y' }))).toEqual([])
})

test('sections are required, unique and known', () => {
  expect(lintTicket('## What to build\nx\n## Plan\ny')).toEqual(
    expect.arrayContaining([
      'Missing section: ## Ownership',
      'Missing section: ## Size',
      'Missing section: ## Acceptance criteria',
      'Unknown section: ## Plan',
    ]),
  )
})

test('size limits refuse an oversized slice', () => {
  expect(
    lintTicket(
      ticket({ size: 'Migrations 1 · New screens 4 · Owned frames 5 · Journeys 2 · Proofs 9' }),
    ),
  ).toEqual([
    'New screens 4 passes its limit 3: split',
    'Owned frames 5 passes its limit 4: split',
    'Journeys 2 passes its limit 1: split',
    'Proofs 9 passes its limit 6: split',
    'A ticket with a migration adds no screens: split backend from screens',
  ])
  expect(lintTicket(ticket({ size: 'Migrations 0' }))).toContain('Size line needs "Proofs <n>"')
})

test('criteria hold one outcome, one proof and no done-definition steps', () => {
  expect(
    lintTicket(
      ticket({
        criteria: [
          '- [ ] Archive saves',
          '- [ ] Archive saves; the list updates - Evidence: test',
          '- [ ] `pnpm verify:local` passes - Evidence: verify',
        ],
      }),
    ),
  ).toEqual([
    'Criterion 1 needs exactly one " - Evidence: <proof>"',
    'Criterion 2 joins outcomes with ";": split it',
    'Criterion 3 restates the done definition (verify, push, evidence, close)',
  ])
  const many = Array.from({ length: 9 }, (_, i) => `- [ ] Outcome ${i} - Evidence: test`)
  expect(lintTicket(ticket({ criteria: many }))).toEqual([
    '9 criteria pass 8: the ticket holds two slices',
  ])
})

test('ownership names owners and What to build stays short', () => {
  const body = ticket({ extra: 'word '.repeat(151) }).replace('restore (#323)', 'restore')
  expect(lintTicket(body)).toEqual([
    'What to build has 154 words; the limit is 150',
    'Out of scope names the issue that owns each item, or reads "none"',
  ])
})
